  struct node *head = malloc(sizeof *head);
  head->val = arr[0];
  head->next = NULL;
  struct node *p = head;
  for(int i=1;i<n;i++){
    p->next = malloc(sizeof *p);
    p->next->val = arr[i];
    p->next->next = NULL;
    p = p->next;
  }
  return head;
}

