fixed:
struct node *unique(struct node *h){
  struct node *p = h;
  while(p){
    struct node *prev = p, *q = p->next;
    while(q){
      if(q->val == p->val){
        prev->next = q->next;
        free(q);
        q = prev->next;
      } else {
        prev = q;
        q = q->next;
      }
    }
    p = p->next;
  }
  return h;
}

