fixed:
int read_n(const char *p, char *buf, int n){
  int fd = open(p, O_RDONLY);
  if(fd < 0) return -1;
  ssize_t total = 0;
  while(total < n){
    ssize_t r = read(fd, buf+total, n-total);
    if(r <= 0) break;
    total += r;
  }
  close(fd);
  return (int)total;
}

